import json
import random
import hashlib
from datetime import datetime

def task_func(utc_datetime, salt='salt', password_length=10, seed=0):
    if not isinstance(utc_datetime, datetime):
        raise ValueError("utc_datetime must be a datetime object")
    if not isinstance(salt, str):
        raise ValueError("salt must be a string")

    if not isinstance(password_length, int) or isinstance(password_length, bool):
        raise ValueError("password_length must be an integer")
    if password_length < 0:
        raise ValueError("password_length must be non-negative")

    random.seed(seed)
    alphabet = "abcdefghijklmnopqrstuvwxyz0123456789"
    password = ''.join(random.choice(alphabet) for _ in range(password_length))

    data = password + salt + str(utc_datetime)
    hashed_password = hashlib.sha256(data.encode("utf-8")).hexdigest()

    return json.dumps(hashed_password)
